#nullable enable // autogenerated

using MVZ2.Managers;
using MVZ2Logic.Models;
using PVZEngine;
using PVZEngine.Tools.Unity;
using UnityEngine;
using UnityEngine.Rendering;

namespace MVZ2.Models
{
    public class ModelManager : MonoBehaviour
    {
        public Texture2D? ShotIconTexture(NamespaceID id, int width, int height, Vector2 modelOffset)
        {
            //激活摄像机与灯光
            var oldActive = modelShotRoot.gameObject.activeSelf;
            modelShotRoot.gameObject.SetActive(true);

            var oldPixelSnap = Shader.GetGlobalInt("_PixelSnap");
            Shader.SetGlobalInt("_PixelSnap", 1);
            try
            {

                //设置模型
                var builder = new ModelBuilder(id, modelShotCamera);
                var modelInstance = builder.Build(modelShotPositionTransform);
                if (!modelInstance.Exists())
                {
                    Debug.LogWarning($"Prefab of model {id} is missing!");
                    return null;
                }
                modelInstance.transform.localPosition = Vector3.zero;
                AlignAllChildrenSpriteRenderers(modelInstance);

                var modelMeta = Main.ResourceManager.GetModelMeta(id);
                if (modelMeta != null && modelMeta.UpdateAnimatorOnShot)
                {
                    modelInstance.UpdateAnimators(0);
                }
                modelInstance.UpdateFrame(0);


                //创建一个用于渲染图片的RenderTexture
                var colorFormat = Main.GraphicsManager.GetSupportedColorFormat();
                var depthFormat = Main.GraphicsManager.GetSupportedDepthFormat();
                var descriptor = new RenderTextureDescriptor(width, height, colorFormat, depthFormat);
                RenderTexture renderTexture = RenderTexture.GetTemporary(descriptor);
                renderTexture.antiAliasing = 1;
                renderTexture.filterMode = FilterMode.Trilinear;
                modelShotCamera.targetTexture = renderTexture;
                modelShotCamera.enabled = false;

                // 相机渲染。
                modelShotCamera.orthographicSize = height * 0.005f;

                var localPos = modelShotPositionTransform.localPosition;
                localPos.x = modelOffset.x * 0.01f;
                localPos.y = modelOffset.y * 0.01f;
                modelShotPositionTransform.localPosition = localPos;

                SortingGroup.UpdateAllSortingGroups();


                // Create a standard request
                RenderPipeline.StandardRequest request = new RenderPipeline.StandardRequest();

                // Check if the request is supported by the active render pipeline
                if (RenderPipeline.SupportsRenderRequest(modelShotCamera, request))
                {
                    // 2D Texture
                    request.destination = renderTexture;
                    // Render camera and fill texture2D with its view
                    RenderPipeline.SubmitRenderRequest(modelShotCamera, request);
                }
                else
                {
                    modelShotCamera.Render();
                }

                // 从Render Texture读取像素并保存为图片
                var texture = CreateTextureFromRenderTexture(renderTexture);
                modelShotCamera.targetTexture = null;
                RenderTexture.ReleaseTemporary(renderTexture);
                DestroyImmediate(modelInstance.gameObject);

                return texture;
            }
            finally
            {
                modelShotRoot.gameObject.SetActive(oldActive);
                Shader.SetGlobalInt("_PixelSnap", oldPixelSnap);
            }
        }
        private Texture2D CreateTextureFromRenderTexture(RenderTexture renderTexture)
        {
            var texture = Main.ResourceManager.GenerateTexture2D(renderTexture.width, renderTexture.height);
            texture.filterMode = FilterMode.Bilinear;
            var oldRT = RenderTexture.active;
            RenderTexture.active = renderTexture;
            try
            {
                texture.ReadPixels(new Rect(0, 0, renderTexture.width, renderTexture.height), 0, 0);
                texture.Apply();
                return texture;
            }
            finally
            {
                RenderTexture.active = oldRT; // 重置活动的Render Texture
            }
        }
        private void AlignAllChildrenSpriteRenderers(Model model)
        {
            var renderers = model.GetComponentsInChildren<SpriteRenderer>();
            foreach (var renderer in renderers)
            {
                var spr = renderer.sprite;
                if (!spr)
                    continue;
                var sprSize = spr.rect.size;
                var pivot = spr.pivot;
                var pixelsPerUnit = spr.pixelsPerUnit;
                var position = renderer.transform.position;
                var scale = renderer.transform.lossyScale;
                var offset = (Vector3)Vector2.Scale(pivot / pixelsPerUnit, scale);
                var minCorner = position - offset;
                var flooredMinCorner = new Vector3(Mathf.Round(minCorner.x * pixelsPerUnit) / pixelsPerUnit, Mathf.Round(minCorner.y * pixelsPerUnit) / pixelsPerUnit, minCorner.z);
                var finalOffset = flooredMinCorner - minCorner;
                renderer.transform.position += finalOffset;
            }
        }
        public MainManager Main => main;
        [SerializeField]
        private MainManager main = null!;
        [SerializeField]
        private Transform modelShotRoot = null!;
        [SerializeField]
        private Transform modelShotPositionTransform = null!;
        [SerializeField]
        private Camera modelShotCamera = null!;
    }
}
